"""Reproducible 1.30 annotation review; preserve source and 1.28 manual provenance."""
import json,runpy
from pathlib import Path
R=Path(__file__).resolve().parents[1]; A=R/'app/src/main/assets'
runpy.run_path(str(R/'tools/refine_wrist_labels.py'))
p=A/'wrist-mri-labels.json';d=json.loads(p.read_text());fs=d['filters']['wrist-mri-3d']
for f in fs:
 if f['id']==91270:f['name']='Остальные связки запястья'
 if f['id']==91271:f['name']='ТФХК'
 if f['id']==1259:f.update(parent=91270,name='Общие ориентиры исходника',default=False)
children=[(91301,91270,'SL / LT · межзапястные'),(91302,91270,'Ладонные связки'),(91303,91270,'Тыльные связки'),(91304,91270,'Другие связки'),(91311,91271,'Диск и прикрепления'),(91312,91271,'Лучелоктевые связки'),(91313,91271,'Периферия ТФХК'),(91314,91271,'Локтезапястные связки'),(91315,91271,'ECU · фиброзный футляр')]
for id,parent,name in children:fs.append({'id':id,'parent':parent,'name':name,'default':True,'icon':'wrist-mri-source/group-1259.png'})
# Source labels remain source labels; no conversion of a general group into a specific ligament.
mapgroup={1632:91311,912701:91301,912702:91301,912703:91311,912704:91311,912706:91311,912707:91311,1636:91303,1645:91303,1641:91304,1649:91304,1650:91304,1640:91313,1639:91314,1638:91313}
rename={1636:'DRC · тыльная лучезапястная связка',1645:'Тыльные межзапястные связки · исходная группа',1640:'Локтевая коллатеральная · условная периферия',1639:'Ладонные локтезапястные связки · общая группа',1638:'Тыльная локтезапястная область · исходная метка',1641:'RCL · лучевая коллатеральная связка',1649:'Гороховидно-крючковидная связка',1650:'Гороховидно-пястная связка'}
for sl in d['slices'].values():
 for t in sl['points']:
  if t['structure'] in mapgroup:t['filter']=mapgroup[t['structure']]
  if t['structure'] in rename:t['name']=rename[t['structure']]
  if t['structure'] in (1638,1639,1640):t.update(approximate=True,color='#FFD27A',name='≈ '+t['name'])
  if 'provenance' not in t:t['provenance']='source-atlas'
notes=d['structureNotes'];notes.update({'1640':'Условный периферический ориентир исходника. Отдельная связка и гомолог мениска на этих точках достоверно не разграничены. Не отождествлять с точной сегментацией UCL.','1645':'Исходная группа тыльных межзапястных связок. Не каждая точка доказывает отдельный пучок DIC.','1639':'Общий исходный ориентир. UL, UT и UC не следует считать автоматически размеченными этой подписью.','1638':'Общий исходный тыльный локтезапястный ориентир. Это не тыльная лучелоктевая связка.'})
# Added regions are explicitly approximate, never presented as segmented fibres.
defs={
 913001:('Ладонная лучелоктевая связка · область',91312,'Ладонный край дистального лучелоктевого сустава. Ориентир по топографии; граница волокон не выделена.'),
 913002:('Тыльная лучелоктевая связка · область',91312,'Тыльный край дистального лучелоктевого сустава. Не путать с DRC или тыльной локтезапястной областью.'),
 913003:('SL · ладонный компонент · область',91301,'Ладонный край ладьевидно-полулунного промежутка. Ручной приблизительный ориентир.'),
 913004:('SL · тыльный компонент · область',91301,'Тыльный край ладьевидно-полулунного промежутка. Ручной приблизительный ориентир.'),
 913005:('LT · ладонный компонент · область',91301,'Ладонный край полулунно-трёхгранного промежутка. Из-за косого хода точка не определяет весь пучок.'),
 913006:('LT · тыльный компонент · область',91301,'Тыльный край полулунно-трёхгранного промежутка. Ручной приблизительный ориентир.'),
 913007:('ECU subsheath · область футляра',91315,'Собственный фиброзный удерживающий футляр ECU у тыльной борозды локтевой кости. Это не синовиальное влагалище. На JPEG стенки футляра отдельно не сегментированы.'),
 913008:('UT · локтево-трёхгранная · область',91314,'Ладонная локтезапястная область к трёхгранной кости. Ожидаемый ход UT; отдельный пучок от соседней капсулы не изолирован.'),
 913009:('UL · локтево-полулунная · область',91314,'Ладонная локтезапястная область к полулунной кости. Ожидаемый ход UL; отдельный пучок от соседней капсулы не изолирован.')}
coords={
 '18667':[(913001,415,357),(913002,399,455),(913007,520,430)],
 '18668':[(913001,413,350),(913002,405,450),(913007,519,434)],
 '18671':[(913003,320,355),(913004,332,433),(913005,419,371),(913006,413,433)],
 '18672':[(913003,314,354),(913004,331,432),(913005,409,360),(913006,406,433)],
 '18712':[(913008,351,241)],'18713':[(913008,350,242)],'18714':[(913009,349,247)]}
added=[]
for sid,pts in coords.items():
 for struct,x,y in pts:
  name,group,note=defs[struct];t={'id':int(sid)*1000+struct%1000,'structure':struct,'name':'≈ '+name,'x':x,'y':y,'filter':group,'color':'#FFD27A','approximate':True,'provenance':'manual-region-review-1.30'}
  d['slices'][sid]['points'].append(t);added.append({'slice':sid,**t});notes[str(struct)]=note
# One row for every requested structure/component; unknown locations have no invented coordinates.
catalog=[]
def item(id,name,group,ids=(),reason=''):
 catalog.append({'id':id,'name':name,'filter':group,'structures':list(ids),'reason':reason or 'Координаты учебные или из исходника; см. пояснение выбранной точки.'})
item('disc','Суставной диск',91311,[1632,912703]);item('central','Диск · центральная часть',91311,[912703]);item('radial','Лучевое прикрепление диска',91311,[912704])
item('vrul','Ладонная лучелоктевая связка',91312,[913001]);item('drul','Тыльная лучелоктевая связка',91312,[913002])
item('fovea','Фовеальное прикрепление',91311,[912706]);item('styloid','Шиловидное прикрепление',91311,[912707])
item('mh','Гомолог мениска',91313,reason='Отдельно от периферической капсулы/UCL на выбранных JPEG надёжно не разграничен. Собственной точки нет.')
item('ul','UL · локтево-полулунная',91314,[913009]);item('ut','UT · локтево-трёхгранная',91314,[913008]);item('uc','UC · локтево-головчатая',91314,reason='Отдельный ход до головчатой кости не прослежен достаточно уверенно. Общая локтезапястная метка не заменяет UC.')
item('ecu','ECU subsheath · фиброзный футляр',91315,[913007]);item('ucl','Локтевая коллатеральная · условная периферия',91313,[1640])
for k,n,ids in [('sl-v','SL · ладонный',[913003]),('sl-m','SL · мембранозный',[912701]),('sl-d','SL · тыльный',[913004]),('lt-v','LT · ладонный',[913005]),('lt-m','LT · мембранозный',[912702]),('lt-d','LT · тыльный',[913006])]:item(k,n,91301,ids)
for k,n in [('rsc','RSC · лучеладьевидно-головчатая'),('lrl','LRL · длинная лучеполулунная'),('srl','SRL · короткая лучеполулунная'),('rsl','RSL · лучеладьевидно-полулунная (Тестю)')]:item(k,n,91302,reason='Самостоятельный пучок не выделен на этом наборе с достаточной уверенностью. Общие исходные ладонные метки не переименованы.')
item('drc','DRC · тыльная лучезапястная',91303,[1636]);item('dic','DIC · тыльная межзапястная',91303,reason='В исходнике есть группа тыльных межзапястных связок, но конкретный пучок DIC отдельно не подтверждён.')
item('dcss','DCSS · тыльная капсулярная SL-перегородка',91303,reason='Тонкая перегородка между тыльной капсулой и SL-комплексом надёжно не разграничена; фиктивная точка не добавлена.')
item('rcl','RCL · лучевая коллатеральная',91304,[1641]);item('stt','STT · связки ладьевидной и костей трапеции/трапециевидной',91304,reason='Комплекс учтён; отдельные связочные пучки не прослежены уверенно.')
item('ph','Гороховидно-крючковидная',91304,[1649]);item('pm','Гороховидно-пястная',91304,[1650]);item('vst','Ладонная ладьевидно-трёхгранная',91302,reason='Не выделена отдельно от других ладонных межзапястных связок.')
item('distal','Межкостные связки дистального ряда',1259,[1647],'Общая исходная группа; индивидуальные пучки не разделены. Сопоставляйте положение с костями на каждом кадре.')
d['catalog']=catalog;d.pop('coverage',None)
d['blocks']=[{'id':91271,'name':'ТФХК'},{'id':91270,'name':'Остальные связки'}];d['storageKey']='wrist-mri-anatomy-v3'
d['searchAliases'].update({str(k):v[0] for k,v in defs.items()});d['review']['version']='1.30'
d['review']['sourceReferences']=['https://pmc.ncbi.nlm.nih.gov/articles/PMC7509702/','https://pubmed.ncbi.nlm.nih.gov/15002101/','https://pubs.rsna.org/doi/10.1148/radiol.2533090743','https://pubmed.ncbi.nlm.nih.gov/24436808/','https://pmc.ncbi.nlm.nih.gov/articles/PMC5381316/']
d['review']['limitations']='Manual regional landmarks are approximate, not fibre segmentation. Catalog includes unlocalized structures with explicit reasons. No independent expert validation.'
p.write_text(json.dumps(d,ensure_ascii=False,separators=(',',':')))
(R/'review/wrist-review-1.30.json').write_text(json.dumps({'catalog':catalog,'added':added,'references':d['review']['sourceReferences']},ensure_ascii=False,indent=2))
print(len(catalog),'catalog entries;',len(added),'new regional points')
